FoamFile
{
    version     2.0;
    format      ascii;
    class       volVectorField;
    object      U;
}

// BFS boundary conditions for backward-facing step
// Inlet: fixedValue (0.075 0 0), Outlet: zeroGradient, Walls: fixedValue (0 0 0)

dimensions      [0 1 -1 0 0 0 0];

internalField   uniform (0.075 0 0);

boundaryField
{
    lid
    {
        type            fixedValue;
        value           uniform (0 0 0);
    }

    fixedWalls
    {
        type            fixedValue;
        value           uniform (0.075 0 0);
    }
}
